%[text] %[text:anchor:H_359B04A7] # **Generation of a quadrilateral mesh**
%[text] It returns a set of points in $X${"editStyle":"visual"}- and $Y${"editStyle":"visual"}-Cartesian directions that provide a structured quadrilateral discretization of the rectangular domain $\\left\\lbrack X\_0 ,X\_{L\_x } \\right\\rbrack \\times \\left\\lbrack Y\_0 ,Y\_{L\_y } \\right\\rbrack${"editStyle":"visual"}:
%[text]{"align":"center"} ![rectangularPlate.png](text:image:236e)
%[text:tableOfContents]{"heading":"**Table of Contents**"}
function [nodesX, nodesY] = generateQuadrilateralMesh(X0, XLx, Y0, YLy, numElx, numEly)
%[text] %[text:anchor:H_D41A3DDC] ## **Function Description**
%[text] It returns the Cartesian coordinates of the nodes corresponding to a mesh of a rectangular plate.
%[text] %[text:anchor:H_C2A6403E]  **Input :**
%[text]  `X0`, `XLx` : Start and end coordinates of the computational domain along the $X${"editStyle":"visual"}-direction
%[text]  `Y0`, `YLy` : Start and end coordinates of the computational domain along the $Y${"editStyle":"visual"}-direction
%[text] `numElx`, `numEly` : Number of elements along the x- and the y-directions
%[text] %[text:anchor:H_CBAFD59D]  **Output :**
%[text] `nodesX`, `nodesY` : $X${"editStyle":"visual"}- and $Y${"editStyle":"visual"}-Cartesian coordinates of the nodes in the mesh
%[text] %[text:anchor:H_D5ED9987] ## Function Implementation
%[text] %[text:anchor:H_7FD342F7] ### Input validation
arguments
    X0 (1, 1) double
    XLx (1, 1) double
    Y0 (1, 1) double
    YLy (1, 1) double
    numElx (1, 1) double {mustBeInteger, mustBePositive}
    numEly (1, 1) double {mustBeInteger, mustBePositive}
end
%[text] %[text:anchor:H_EE07995C] ### Generation of a structured discretization both along *X*- and *Y*-Cartesian directions
isMeshEquispaced = true; % Render the mesh non-equispaced %[control:checkbox:674c]{"position":[20,24]}
nodes_alongX = linspace(X0, XLx, numElx + 1)';
nodes_alongY = linspace(Y0, YLy, numEly + 1)';
if ~isMeshEquispaced
    nodes_alongX = [0 0.4 0.9 1.6 2]';
    nodes_alongY = [0 0.6 1]';
end
nodesX = repmat(nodes_alongX, 1, numEly + 1)';
nodesY = repmat(nodes_alongY, numElx + 1, 1);
%[text] %[text:anchor:H_48681EF2] ### Render the mesh non-uniform by modifying some of the nodal coordinates (it only works for `numElx = 4` and `numEly = 2`)
isMeshUniform = true; %[control:checkbox:8ebd]{"position":[17,21]}
if ~isMeshUniform
    if numElx ~= 4 || numEly ~= 2
        error("Making the mesh non-uniform only works for numElx = 4 and numEly = 2")
    end
    % Move node 2
    nodesY(2, 1) = nodesY(2, 1) + 0.08; % y

    % Move node 5
    nodesX(2, 2) = nodesX(2, 2) + 0.08; % x
    nodesY(5, 1) = nodesY(5, 1) - 0.08; % y
    
    % Move node 8
    nodesX(2, 3) = nodesX(2, 3) - 0.08; % x
    nodesY(8, 1) = nodesY(8, 1) + 0.08; % y
    
    % Move node 11
    nodesX(2, 4) = nodesX(2, 4) + 0.08; % x
    nodesY(11, 1) = nodesY(11, 1) + 0.08; % x
    
    % Move node 14
    nodesY(14, 1) = nodesY(14, 1) - 0.08; % x
end
%[text] 
end

